```javascript
import * as THREE from 'three/webgpu';
import { gsap } from 'gsap';

export default function createNode(config, ctx) {
  const group = new THREE.Group();

  // Rail dimensions
  const RAIL_W = 3.6, RAIL_H = 0.5, RAIL_D = 0.05, CORNER_R = 0.1;
  const RAIL_Z = 0.15;

  // === Rail Mesh with Machined-Metal PBR ===
  const canvas = document.createElement('canvas');
  canvas.width = 1;
  canvas.height = 256;
  const c2d = canvas.getContext('2d');
  const grad = c2d.createLinearGradient(0, 0, 0, 256);
  grad.addColorStop(0, '#1b1b23');
  grad.addColorStop(1, '#101015');
  c2d.fillStyle = grad;
  c2d.fillRect(0, 0, 1, 256);

  const albedo = new THREE.CanvasTexture(canvas);
  albedo.colorSpace = THREE.SRGBColorSpace;

  const railGeom = new THREE.RoundedBoxGeometry(
    RAIL_W, RAIL_H, RAIL_D, 16, 8, 8, CORNER_R
  );
  const railMat = new THREE.MeshStandardMaterial({
    map: albedo,
    metalness: 0.5, roughness: 0.55, anisotropy: 0.6, anisotropyRotation: 0,
    clearcoat: 0.2,
  });
  const rail = new THREE.Mesh(railGeom, railMat);
  rail.position.z = RAIL_Z;
  group.add(rail);

  // === Contact Shadow ===
  const shadowGeom = new THREE.PlaneGeometry(RAIL_W + 0.2, RAIL_H + 0.2);
  const shadowMat = new THREE.MeshBasicMaterial({
    color: 0x000000, transparent: true, opacity: 0.35,
  });
  const shadow = new THREE.Mesh(shadowGeom, shadowMat);
  shadow.position.set(0, -0.06, 0);
  group.add(shadow);

  // === Navigation Items ===
  const items = [
    { label: 'HOME', active: true },
    { label: 'FEATURES', active: false },
    { label: 'COLLECTION', active: false },
    { label: 'PRICING', active: false },
    { label: 'JOURNAL', active: false },
  ];

  const ENTRY_SPACE = 0.68, ENTRY_W = 0.6, ENTRY_H = 0.34;
  const START_X = -(ENTRY_SPACE * 2);

  let activeIdx = 0;
  const texts = [];
  const hits = [];

  items.forEach((item, i) => {
    const x = START_X + i * ENTRY_SPACE;

    const text = ctx.fontAtlas.create(item.label, {
      fontSize: 13, fontWeight: item.active ? 700 : 400,
      fontFamily: 'JetBrains Mono', letterSpacing: 0.08,
      color: item.active ? 0xe8ecf2 : 0xa6adba,
    });
    text.position.set(x, 0, RAIL_Z + 0.01);
    text.userData.navIndex = i;
    group.add(text);
    texts.push(text);

    const hitGeom = new THREE.PlaneGeometry(ENTRY_W, ENTRY_H);
    const hitMat = new THREE.MeshBasicMaterial({ transparent: true, opacity: 0 });
    const hit = new THREE.Mesh(hitGeom, hitMat);
    hit.position.set(x, 0, RAIL_Z + 0.05);
    hit.userData.navIndex = i;
    group.add(hit);
    hits.push(hit);
  });

  // === Active Indicator Bar ===
  const barGeom = new THREE.PlaneGeometry(0.28, 0.025);
  const barMat = new THREE.MeshBasicMaterial({
    color: 0xff2a38, emissive: 0xff2a38, emissiveIntensity: 1.8,
  });
  const bar = new THREE.Mesh(barGeom, barMat);
  bar.position.set(START_X, -0.06, RAIL_Z + 0.01);
  group.add(bar);

  // === Event Handlers ===
  group.userData.handlers = {
    click: (e) => {
      const intersections = e.intersections || [];
      for (const hit of intersections) {
        if (!hits.includes(hit.object)) continue;

        const i = hit.object.userData.navIndex;
        if (i !== activeIdx) {
          activeIdx = i;

          const tx = START_X + i * ENTRY_SPACE;
          gsap.to(bar.position, {
            x: tx, duration: 0.26,
            ease: 'cubic-bezier(0.165, 0.84, 0.44, 1)',
          });

          texts.forEach((t, ti) => {
            const col = ti === i ? 0xe8ecf2 : 0xa6adba;
            const r = (col >> 16) & 255, g = (col >> 8) & 255, b = col & 255;
            gsap.to(t.material.color, {
              r: r / 255, g: g / 255, b: b / 255, duration: 0.26,
            });
          });
        }

        gsap.to(hit.object.position, {
          z: '-=0.03', duration: 0.12,
          ease: 'cubic-bezier(0.175, 0.885, 0.32, 1.275)',
          yoyo: true, repeat: 1,
        });
        gsap.to(hit.object.scale, {
          x: 0.97, y: 0.97, duration: 0.12,
          ease: 'cubic-bezier(0.175, 0.885, 0.32, 1.275)',
          yoyo: true, repeat: 1,
        });
      }
    },

    mousemove: (e) => {
      const hovered = new Set(
        (e.intersections || [])
          .filter((h) => hits.includes(h.object))
          .map((h) => h.object.userData.navIndex)
      );

      texts.forEach((t, i) => {
        const col = (i === activeIdx || hovered.has(i)) ? 0xe8ecf2 : 0xa6adba;
        const r = (col >> 16) & 255, g = (col >> 8) & 255, b = col & 255;
        gsap.to(t.material.color, {
          r: r / 255, g: g / 255, b: b / 255, duration: 0.16,
          ease: 'cubic-bezier(0.25, 0.46, 0.45, 0.94)',
          overwrite: 'auto',
        });
      });
    },
  };

  // === Mount Animation ===
  group.position.y = 0.4;
  gsap.to(group.position, {
    y: 0, duration: 0.7,
    ease: 'cubic-bezier(0.215, 0.61, 0.355, 1)',
  });

  // === Cleanup ===
  group.userData.cleanup = () => {
    gsap.killTweensOf([
      group.position, bar.position,
      ...texts.map((t) => t.material.color),
      ...hits.flatMap((h) => [h.position, h.scale]),
    ]);

    railGeom.dispose();
    railMat.dispose();
    albedo.dispose();
    shadowGeom.dispose();
    shadowMat.dispose();
    barGeom.dispose();
    barMat.dispose();

    texts.forEach((t) => { t.geometry?.dispose(); t.material?.dispose(); });
    hits.forEach((h) => { h.geometry.dispose(); h.material.dispose(); });
  };

  return group;
}
